interface Greeter {
    fn greet(self) -> String
}
interface Describable {
    fn describe(self) -> String
}
record User { name: String }
impl Greeter for User {
    fn greet(self) -> String {
        "hi"
    }
}
impl Describable for User {
    fn describe(self) -> String {
        "u"
    }
}
fn f(d: Dyn<Greeter>) -> String {
    d.describe()
}

